<?php
namespace qqworld_collector\module\artificial_intelligence; if (!defined('ABSPATH')) { exit; } class QQWorld_AI_Search { private $settings_name = 'qqworld-collector-artificial-intelligence-settings'; public function search($query, $max_results = 5) { $settings = get_option($this->settings_name, array()); $mode = isset($settings['web-search']) ? $settings['web-search'] : 'auto'; switch ($mode) { case 'bing': return $this->search_bing_api($query, $max_results, $settings); case 'baidu': return $this->search_baidu_api($query, $max_results, $settings); case 'duckduckgo': return $this->search_duckduckgo_api($query, $max_results, $settings); case 'auto': default: return $this->search_auto($query, $max_results); } } private function search_auto($query, $max_results) { $results = $this->search_bing_scraper($query, $max_results); if (!empty($results)) { return array( 'results' => $results, 'engine' => 'Bing Scraper', 'count' => count($results), ); } return array( 'results' => array(), 'engine' => '', 'count' => 0, ); } private function search_bing_api($query, $max_results, $settings) { $api_key = isset($settings['bing-api-key']) ? $settings['bing-api-key'] : ''; $endpoint = isset($settings['bing-endpoint']) ? $settings['bing-endpoint'] : 'https://api.bing.microsoft.com/v7.0/search'; if (empty($api_key)) { error_log('[QQWorld AI Search] Bing API key not configured, falling back to scraper'); return $this->search_bing_scraper($query, $max_results); } $url = $endpoint . '?q=' . urlencode($query) . '&count=' . $max_results; $response = wp_remote_get($url, array( 'headers' => array( 'Ocp-Apim-Subscription-Key' => $api_key, ), 'timeout' => 15, )); if (is_wp_error($response)) { error_log('[QQWorld AI Search] Bing API error: ' . $response->get_error_message()); return $this->search_bing_scraper($query, $max_results); } $body = json_decode(wp_remote_retrieve_body($response), true); $results = array(); if (isset($body['webPages']['value']) && is_array($body['webPages']['value'])) { foreach ($body['webPages']['value'] as $item) { $results[] = array( 'title' => isset($item['name']) ? $item['name'] : '', 'href' => isset($item['url']) ? $item['url'] : '', 'body' => isset($item['snippet']) ? $item['snippet'] : '', 'source' => 'bing_api', ); } } if (!empty($results)) { return array( 'results' => $results, 'engine' => 'Bing API', 'count' => count($results), ); } return $this->search_bing_scraper($query, $max_results); } private function search_baidu_api($query, $max_results, $settings) { $ak = isset($settings['baidu-ak']) ? $settings['baidu-ak'] : ''; $sk = isset($settings['baidu-sk']) ? $settings['baidu-sk'] : ''; if (empty($ak) || empty($sk)) { error_log('[QQWorld AI Search] Baidu API credentials not configured'); return array( 'results' => array(), 'engine' => '', 'count' => 0, ); } $timestamp = time(); $sign = md5($ak . $query . $timestamp . $sk); $url = 'https://api.baidu.com/json/rpc/2.1/registry/v1/search/web?qt=web&wd=' . urlencode($query) . '&rn=' . $max_results . '&ie=utf-8&ak=' . $ak . '&timestamp=' . $timestamp . '&sign=' . $sign; $response = wp_remote_get($url, array( 'timeout' => 15, )); if (is_wp_error($response)) { error_log('[QQWorld AI Search] Baidu API error: ' . $response->get_error_message()); return array( 'results' => array(), 'engine' => '', 'count' => 0, ); } $body = json_decode(wp_remote_retrieve_body($response), true); $results = array(); if (isset($body['result']) && is_array($body['result'])) { foreach ($body['result'] as $item) { $results[] = array( 'title' => isset($item['title']) ? strip_tags($item['title']) : '', 'href' => isset($item['url']) ? $item['url'] : '', 'body' => isset($item['abstract']) ? strip_tags($item['abstract']) : '', 'source' => 'baidu_api', ); } } return array( 'results' => $results, 'engine' => !empty($results) ? 'Baidu API' : '', 'count' => count($results), ); } private function search_duckduckgo_api($query, $max_results, $settings) { $token = isset($settings['duckduckgo-token']) ? $settings['duckduckgo-token'] : ''; $url = 'https://api.duckduckgo.com/?q=' . urlencode($query) . '&format=json&no_html=1&skip_disambig=1'; $headers = array(); if (!empty($token)) { $headers['Authorization'] = 'Bearer ' . $token; } $response = wp_remote_get($url, array( 'headers' => $headers, 'timeout' => 15, )); if (is_wp_error($response)) { error_log('[QQWorld AI Search] DuckDuckGo API error: ' . $response->get_error_message()); return array( 'results' => array(), 'engine' => '', 'count' => 0, ); } $body = json_decode(wp_remote_retrieve_body($response), true); $results = array(); if (isset($body['AbstractText']) && !empty($body['AbstractText'])) { $results[] = array( 'title' => isset($body['Heading']) ? $body['Heading'] : $query, 'href' => isset($body['AbstractURL']) ? $body['AbstractURL'] : '', 'body' => $body['AbstractText'], 'source' => 'duckduckgo_api', ); } if (isset($body['RelatedTopics']) && is_array($body['RelatedTopics'])) { foreach ($body['RelatedTopics'] as $item) { if (count($results) >= $max_results) break; if (isset($item['Text']) && !empty($item['Text'])) { $results[] = array( 'title' => isset($item['Text']) ? mb_substr($item['Text'], 0, 100) : '', 'href' => isset($item['FirstURL']) ? $item['FirstURL'] : '', 'body' => isset($item['Text']) ? $item['Text'] : '', 'source' => 'duckduckgo_api', ); } } } return array( 'results' => $results, 'engine' => !empty($results) ? 'DuckDuckGo' : '', 'count' => count($results), ); } private function search_bing_scraper($query, $max_results) { $url = 'https://cn.bing.com/search?q=' . urlencode($query) . '&count=' . $max_results; $ch = curl_init(); curl_setopt($ch, CURLOPT_URL, $url); curl_setopt($ch, CURLOPT_RETURNTRANSFER, 1); curl_setopt($ch, CURLOPT_USERAGENT, 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/125.0.0.0 Safari/537.36'); curl_setopt($ch, CURLOPT_FOLLOWLOCATION, 1); curl_setopt($ch, CURLOPT_SSL_VERIFYPEER, false); curl_setopt($ch, CURLOPT_TIMEOUT, 15); $html = curl_exec($ch); if (curl_errno($ch)) { error_log('[QQWorld AI Search] Bing cURL error: ' . curl_error($ch)); curl_close($ch); return array(); } curl_close($ch); error_log('[QQWorld AI Search] Bing response length: ' . strlen($html)); if (strlen($html) < 1000) { error_log('[QQWorld AI Search] Bing response too short'); return array(); } if (strpos($html, 'captcha') !== false || strpos($html, '人机验证') !== false) { error_log('[QQWorld AI Search] Bing blocked by captcha'); return array(); } $dom = new \DOMDocument(); libxml_use_internal_errors(true); $dom->loadHTML('<?xml encoding="UTF-8">' . $html); libxml_clear_errors(); $xpath = new \DOMXPath($dom); $results = $xpath->query('//li[contains(@class, "b_algo")]'); $data = array(); if ($results !== false) { foreach ($results as $result) { $titleNode = $xpath->query('.//h2/a', $result)->item(0); $title = $titleNode ? trim($titleNode->nodeValue) : ''; $link = $titleNode ? trim($titleNode->getAttribute('href')) : ''; $snippet = ''; $captionNodes = $xpath->query('.//div[contains(@class, "b_caption")]', $result); if ($captionNodes->length > 0) { $pNodes = $xpath->query('.//p', $captionNodes->item(0)); if ($pNodes->length > 0) { $snippet = trim($pNodes->item(0)->nodeValue); } } if (!empty($title) && !empty($link)) { $data[] = array( 'title' => $title, 'href' => $link, 'body' => $snippet, 'source' => 'bing_scraper', ); } if (count($data) >= $max_results) { break; } } } error_log('[QQWorld AI Search] Bing returned ' . count($data) . ' results'); return $data; } } 